export const MaxBlockDelayMs = 1000 * 60 * 60 * 6; // 6 hours

// Successful activation checks are immutable for the lifetime of a process:
// NEAR protocol versions only move forward. Failed checks are deliberately not
// cached so a long-running process can start using the feature after an upgrade.
// Protocol 85 enabled ML-DSA-65 keys, gas keys and TransactionV1 together, so
// one gate serves all of them; `feature` names the caller's need in the error.
const protocol85RpcUrls = new Set<string>();

async function ensureProtocol85(targetNetwork: FastNearNetworkId, feature: string): Promise<void> {
  const rpcUrl = resolveRpcUrl(resolveConfigForCall(targetNetwork));
  if (protocol85RpcUrls.has(rpcUrl)) return;
  const protocolVersion = await queryProtocolVersion({ network: targetNetwork });
  if (protocolVersion < 85) {
    throw new Error(`${feature} requires v85+; got ${protocolVersion}`);
  }
  protocol85RpcUrls.add(rpcUrl);
}

function isMlDsa65Key(value: unknown): value is `ml-dsa-65:${string}` {
  return typeof value === "string" && value.startsWith("ml-dsa-65:");
}

function assertGasKeyNumNonces(numNonces: unknown): asserts numNonces is number {
  if (
    !Number.isInteger(numNonces) ||
    (numNonces as number) < 1 ||
    (numNonces as number) > MAX_GAS_KEY_NONCES
  ) {
    throw new Error(
      `numNonces must be an integer between 1 and ${MAX_GAS_KEY_NONCES} ` +
        "(each nonce is an independent transaction lane; the AddKey fee scales with it)",
    );
  }
}

interface ActionInspection {
  usesMlDsa: boolean;
  usesGasKeys: boolean;
}

function inspectAction(action: any): ActionInspection {
  const type = action?.type;
  let usesGasKeys = false;
  if (type === "Stake") {
    assertNearValidatorPublicKey(action.publicKey);
  } else if (type === "AddKey" || type === "DeleteKey") {
    decodeNearPublicKey(action.publicKey);
    if (type === "AddKey" && isGasKeyPermission(action.accessKey?.permission)) {
      usesGasKeys = true;
      // The chain rejects AddKey with a funded gas key; the codec keeps the
      // field so decoded payloads re-encode, so police it here at ingress.
      if (BigInt(action.accessKey.balance ?? 0) !== 0n) {
        throw new Error(
          "AddKey gas-key balance must be 0; fund the key afterwards with TransferToGasKey",
        );
      }
    }
  } else if (type === "TransferToGasKey" || type === "WithdrawFromGasKey") {
    decodeNearPublicKey(action.publicKey);
    usesGasKeys = true;
  }
  let usesMlDsa = isMlDsa65Key(action?.publicKey) ||
    isMlDsa65Key(action?.signature);
  if (type === "SignedDelegate") {
    const delegate = action.delegateAction;
    decodeNearPublicKey(delegate?.publicKey);
    usesMlDsa ||= isMlDsa65Key(delegate.publicKey);
    if (action.publicKey !== undefined && action.publicKey !== delegate.publicKey) {
      throw new Error("SignedDelegate publicKey must match delegateAction.publicKey");
    }
    const nested = inspectActions(delegate.actions);
    usesMlDsa ||= nested.usesMlDsa;
    usesGasKeys ||= nested.usesGasKeys;
  }
  return { usesMlDsa, usesGasKeys };
}

function inspectActions(actions: readonly any[]): ActionInspection {
  // Inspect every action (validation side effects), then merge the flags.
  return actions.reduce<ActionInspection>(
    (acc, action) => {
      const one = inspectAction(action);
      return {
        usesMlDsa: acc.usesMlDsa || one.usesMlDsa,
        usesGasKeys: acc.usesGasKeys || one.usesGasKeys,
      };
    },
    { usesMlDsa: false, usesGasKeys: false },
  );
}

function normalizeActionParams(action: any): Record<string, any> {
  if (!action || typeof action !== "object") {
    return {};
  }
  if (action.params && typeof action.params === "object") {
    return { ...action.params };
  }
  const { type, ...rest } = action;
  return { ...rest };
}

function looksRetryable(message: string, code: string | number | null, kind: ExplainedError["kind"]): boolean {
  if (kind === "transport_error") {
    return true;
  }
  // Match what the transport ACTUALLY retries. For HTTP status, that is the
  // broad `isRetryableStatus` (408/429 and any 5xx) — not the narrow display
  // list, which omitted the Cloudflare edge codes 520/522/524 the transport
  // does retry, so `explain.error().retryable` reported false for an error the
  // client had just retried five times. JSON-RPC codes (negative) still come
  // from RETRYABLE_RPC_CODES, since isRetryableStatus only speaks HTTP.
  if (
    typeof code === "number" &&
    (isRetryableStatus(code) || (RETRYABLE_RPC_CODES as readonly number[]).includes(code))
  ) {
    return true;
  }
  return /timeout|temporar|temporarily|rate limit|unavailable|network|gateway/i.test(message);
}

function parseErrorPayload(error: unknown): {
  code: string | number | null;
  name: string | null;
  message: string;
  data: any;
  kind: ExplainedError["kind"];
} {
  const fallbackMessage = error instanceof Error
    ? error.message
    : typeof error === "string"
      ? error
      : "Unknown error";

  const parsedMessage = tryParseJson(fallbackMessage);
  const parsedObject = parsedMessage && typeof parsedMessage === "object"
    ? parsedMessage
    : error && typeof error === "object"
      ? error
      : null;

  const code = parsedObject && "code" in parsedObject ? (parsedObject as any).code : null;
  const data = parsedObject && "data" in parsedObject
    ? (parsedObject as any).data
    : parsedMessage && parsedMessage !== parsedObject
      ? parsedMessage
      : null;
  const name = error instanceof Error
    ? error.name
    : parsedObject && "name" in parsedObject
      ? String((parsedObject as any).name)
      : "Error";
  const message = parsedObject && "message" in parsedObject
    ? String((parsedObject as any).message)
    : fallbackMessage;

  let kind: ExplainedError["kind"] = "error";
  if (parsedObject && ("code" in parsedObject || "data" in parsedObject)) {
    kind = "rpc_error";
  } else if (/wallet/i.test(message)) {
    kind = "wallet_error";
  } else if (/network|timeout|fetch|gateway|unavailable/i.test(message)) {
    kind = "transport_error";
  }

  return {
    code,
    name,
    message,
    data,
    kind,
  };
}

export function withBlockId(params: Record<string, any>, blockId?: string) {
  if (blockId === "final" || blockId === "optimistic") {
    return { ...params, finality: blockId };
  }
  return blockId ? { ...params, block_id: blockId } : { ...params, finality: "optimistic" };
}

type ServiceFamily = "rpc" | "api" | "tx" | "transfers" | "neardata" | "fastdata.kv";
type ServiceAuthStyle = "none" | "bearer" | "query";

interface ServiceRequestOptions {
  family: Exclude<ServiceFamily, "rpc">;
  path: string;
  method?: "GET" | "POST";
  query?: Record<string, any>;
  body?: any;
  headers?: Record<string, string>;
  // When set, routes the request through the override network's defaults
  // (URLs from `NETWORKS[network].services.*`) instead of the active
  // config. The active config's `apiKey` still flows through. Without
  // it, the active config is used end-to-end.
  network?: FastNearNetworkId;
}

const SERVICE_AUTH_STYLES: Record<ServiceFamily, ServiceAuthStyle> = {
  rpc: "query",
  api: "bearer",
  tx: "bearer",
  transfers: "bearer",
  neardata: "query",
  "fastdata.kv": "bearer",
};

function omitUndefinedEntries<T extends Record<string, any>>(value?: T): T | undefined {
  if (!value) {
    return undefined;
  }

  return Object.fromEntries(
    Object.entries(value).filter(([, entry]) => entry !== undefined)
  ) as T;
}

function buildUrl(baseUrl: string, path: string, query?: Record<string, any>): string {
  const url = new URL(path.replace(/^\/+/, ""), `${baseUrl.replace(/\/+$/, "")}/`);
  for (const [key, value] of Object.entries(query ?? {})) {
    if (value === undefined || value === null) {
      continue;
    }
    if (Array.isArray(value)) {
      value.forEach((item) => {
        if (item !== undefined && item !== null) {
          url.searchParams.append(key, String(item));
        }
      });
      continue;
    }
    url.searchParams.set(key, String(value));
  }
  return url.toString();
}

// Resolve the config to use for a per-call override. Without an
// override, returns the active config. With one, returns a config built
// from `NETWORKS[network].services` (so URLs hit the right hosts) but
// inheriting the active `apiKey` (which is account-bound, not
// network-bound). User-applied per-network URL overrides via
// `near.config({ services: …, networkId: "testnet" })` are not currently
// preserved across cross-network calls — callers who need that should
// switch via `near.config({ networkId })` and back.
function resolveConfigForCall(network?: FastNearNetworkId): NetworkConfig {
  const active = getConfig();
  if (!network || network === active.networkId) {
    return active;
  }
  // Reuse the same chain-scoped/client-scoped split `setConfig` uses, rather
  // than re-listing the fields that carry. This used to name `apiKey` and
  // `retry` explicitly and silently dropped `batch` — and would have dropped
  // any field added later. Now a per-call network override keeps everything
  // the caller configured, exactly like switching network does.
  return resolveConfig({}, rebaseConfigToNetwork(active, network));
}

function resolveServiceBaseUrl(family: Exclude<ServiceFamily, "rpc">, config: NetworkConfig): string {
  const baseUrl = family === "fastdata.kv"
    ? config.services?.fastdata?.kvBaseUrl
    : config.services?.[family]?.baseUrl;

  if (!baseUrl) {
    if (family === "transfers" && config.networkId === "testnet") {
      throw new Error(
        "fastnear: transfers service is not configured for testnet; set services.transfers.baseUrl",
      );
    }
    throw new Error(`fastnear: ${family} service is not configured for ${config.networkId}.`);
  }

  return baseUrl;
}

function resolveRpcUrl(config: NetworkConfig): string {
  const rpcUrl = config.nodeUrl || config.services?.rpc?.baseUrl;
  if (!rpcUrl) {
    throw new Error("fastnear: getConfig() returned invalid config: missing nodeUrl.");
  }
  return rpcUrl;
}

// Pick the archival RPC if configured; fall back to the regular RPC so
// callers that opt into `useArchival` against a network without archival
// configured still get an answer (just from the non-archival node).
function resolveArchivalUrl(config: NetworkConfig): string {
  return config.services?.archival?.baseUrl || resolveRpcUrl(config);
}

function buildAuthedUrl(
  service: ServiceFamily,
  baseUrl: string,
  path = "",
  query?: Record<string, any>,
  config: NetworkConfig = getConfig(),
): string {
  const authStyle = SERVICE_AUTH_STYLES[service];
  const authQuery =
    authStyle === "query" && config.apiKey
      ? { ...(query || {}), apiKey: config.apiKey }
      : query;

  return buildUrl(baseUrl, path, authQuery);
}

async function sendServiceRequest<T = any>({
  family,
  path,
  method = "GET",
  query,
  body,
  headers = {},
  network,
}: ServiceRequestOptions): Promise<T> {
  const config = resolveConfigForCall(network);
  const authStyle = SERVICE_AUTH_STYLES[family];
  // Build the URL up front so a service misconfiguration (e.g. transfers on
  // testnet) still throws synchronously, with zero fetch attempts.
  const url = buildAuthedUrl(family, resolveServiceBaseUrl(family, config), path, query, config);
  const requestHeaders: Record<string, string> = { ...headers };

  if (authStyle === "bearer" && config.apiKey) {
    requestHeaders.Authorization = `Bearer ${config.apiKey}`;
  }

  let requestBody: string | undefined;
  if (body !== undefined) {
    requestHeaders["Content-Type"] = requestHeaders["Content-Type"] || "application/json";
    requestBody = JSON.stringify(body);
  }

  const cfg = (config.retry as ResolvedRetryConfig) ?? DEFAULT_RETRY;
  const outcome = await runWithRetry(cfg, false, (signal) =>
    serviceSend(family, url, method, requestHeaders, requestBody, signal),
  );
  if (outcome.kind === "ok") {
    return outcome.value as T;
  }
  throw outcomeError(outcome);
}

export interface RpcRouteOptions {
  /**
   * Route this call to the archival RPC (`services.archival.baseUrl`)
   * instead of the default. Useful for queries with a historical
   * `blockId`. Falls back to the regular RPC if archival isn't configured.
   */
  useArchival?: boolean;
  /**
   * Route this call to the override network's RPC instead of the active
   * `near.config().networkId`. Useful when a page holds parallel
   * mainnet+testnet sessions and a single read or write needs to target
   * the non-active network without flipping config back and forth.
   */
  network?: FastNearNetworkId;
}

// Write RPCs must never be batched, and retry only per the config's
// writePolicy (default: pre-response transport failures only).
const WRITE_METHODS = new Set<string>([
  "send_tx",
  "send_tx_async",
  "broadcast_tx_commit",
  "broadcast_tx_async",
]);

// Resolve a call's full route: the authed POST URL (which folds in network,
// archival, rpcUrl and apiKey) plus the resolved retry policy.
function resolveRpcRoute(options?: RpcRouteOptions): RpcRoute {
  const config = resolveConfigForCall(options?.network);
  const useArchival = !!options?.useArchival;
  const baseUrl = useArchival ? resolveArchivalUrl(config) : resolveRpcUrl(config);
  const url = buildAuthedUrl("rpc", baseUrl, "", undefined, config);
  return {
    url,
    networkId: config.networkId,
    useArchival,
    retry: (config.retry as ResolvedRetryConfig) ?? DEFAULT_RETRY,
  };
}

export async function sendRpc<T = any>(
  method: string,
  params: Record<string, any> | any[],
  options?: RpcRouteOptions,
): Promise<T> {
  const route = resolveRpcRoute(options);
  // Serialize once so every retry attempt sends byte-identical bytes
  // (write-safe: resending the same signed tx is deduped by hash).
  const bodyStr = JSON.stringify({ jsonrpc: "2.0", id: nextRpcId(), method, params });
  const isWrite = WRITE_METHODS.has(method);
  const outcome = await runWithRetry<T>(route.retry, isWrite, (signal) =>
    rpcSend(route, bodyStr, signal),
  );
  if (outcome.kind === "ok") {
    return outcome.value as T;
  }
  throw outcomeError(outcome);
}

export interface BatchRequest {
  method: string;
  params: Record<string, any> | any[];
  useArchival?: boolean;
  network?: FastNearNetworkId;
}

export type BatchItemResult<T = any> =
  | { status: "ok"; result: T }
  | { status: "error"; kind: RpcErrorKind | "unknown"; error: any };

// Tag each settled error with its category so callers can tell an application
// (smart-contract) failure from an infra one without re-parsing the error.
const errorKind = (error: unknown): RpcErrorKind | "unknown" =>
  error instanceof FastNearRpcError ? error.kind : "unknown";

/**
 * Explicit bulk API: run many RPC calls, each as its own retried request, with
 * at most `batch.maxConcurrency` (default 30) in flight — the lever that curbs
 * 429s without bursting. (NEAR RPC has no array batching, so calls can't be
 * collapsed into one request.) Returns settled results in input order — one
 * failing call never rejects the whole set. Write methods (`send_tx` /
 * `broadcast_tx_*`) are rejected per-item.
 */
export const batch = async (requests: BatchRequest[]): Promise<BatchItemResult[]> => {
  const { maxConcurrency } = resolveBatchConfig(getConfig());
  return mapWithConcurrency(requests, maxConcurrency, async (req): Promise<BatchItemResult> => {
    // Everything in the try, so a malformed item settles as an error instead of
    // rejecting the whole set.
    try {
      if (WRITE_METHODS.has(req.method)) {
        return { status: "error", kind: "unknown", error: new Error(`fastnear: method "${req.method}" cannot be batched`) };
      }
      const result = await sendRpc(req.method, req.params, { useArchival: req.useArchival, network: req.network });
      return { status: "ok", result };
    } catch (error) {
      return { status: "error", kind: errorKind(error), error };
    }
  });
};

export function afterTxSent(txId: string, network?: FastNearNetworkId) {
  const txHistory = getTxHistory();
  sendRpc("tx", {
    tx_hash: txHistory[txId]?.txHash,
    sender_account_id: txHistory[txId]?.tx?.signerId,
    wait_until: "EXECUTED_OPTIMISTIC",
  }, { network })
    .then( result => {
      const successValue = result?.result?.status?.SuccessValue;
      updateTxHistory({
        txId,
        status: "Executed",
        result,
        successValue: successValue ? tryParseJson(fromBase64(successValue)) : undefined,
        finalState: true,
      });
    })
    .catch((error) => {
      updateTxHistory({
        txId,
        status: "ErrorAfterIncluded",
        error: tryParseJson(error.message) ?? error.message,
        finalState: true,
      });
    });
}

export async function sendTxToRpc(
  signedTxBase64: string,
  waitUntil: string | undefined,
  txId: string,
  network?: FastNearNetworkId,
) {
  // default to "INCLUDED"
  // see options: https://docs.near.org/api/rpc/transactions#tx-status-result
  waitUntil = waitUntil || "INCLUDED";

  try {
    const sendTxRes = await sendRpc("send_tx", {
      signed_tx_base64: signedTxBase64,
      wait_until: waitUntil,
    }, { network });

    updateTxHistory({ txId, status: "Included", finalState: false });
    afterTxSent(txId, network);

    return sendTxRes;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    updateTxHistory({
      txId,
      status: "Error",
      error: tryParseJson(errorMessage) ?? errorMessage,
      finalState: false,
    });
    throw new Error(errorMessage);
  }
}

/**
 * Generates a mock transaction ID.
 */
export function generateTxId(): string {
  const randomPart = crypto.getRandomValues(new Uint32Array(2)).join("");
  return `tx-${Date.now()}-${parseInt(randomPart, 10).toString(36)}`;
}

export const accountId = (options: { network?: FastNearNetworkId } = {}) =>
  getAccountState(options.network).accountId;

export const publicKey = (options: { network?: FastNearNetworkId } = {}) =>
  getAccountState(options.network).publicKey;

export const config = (newConfig?: Partial<NetworkConfig>) => {
  const current = getConfig();
  if (newConfig) {
    const networkChanging =
      !!newConfig.networkId && current.networkId !== newConfig.networkId;
    setConfig(newConfig);
    if (networkChanging) {
      // Per-network state and per-network block cache are preserved
      // across config switches — each network's slot survives. tx
      // history is still cleared because it's keyed by local txId, not
      // network, and a switch is the natural boundary for "I'm done
      // with the previous network's recent activity."
      resetTxHistory();
    }
    // Whenever a `networkId` is explicitly specified, pin the active
    // cursor to it — even when config.networkId was already that value.
    // Callers use `config({ networkId })` as the canonical "switch
    // default network" idiom, so it should also flip active.
    if (newConfig.networkId) {
      setActiveNetwork(getConfig().networkId);
    }
  }
  return getConfig();
};

export const authStatus = (
  options: { network?: FastNearNetworkId } = {},
): string | Record<string, any> => {
  return getAccountState(options.network).accountId ? "SignedIn" : "SignedOut";
};

export const getPublicKeyForContract = (options: { network?: FastNearNetworkId } = {}) => {
  return publicKey(options);
}

export const selected = (options: { network?: FastNearNetworkId } = {}) => {
  const network = options.network ?? getActiveNetwork();
  const slot = getAccountState(network);

  return {
    network,
    nodeUrl: getConfig().nodeUrl,
    walletUrl: getConfig().walletUrl,
    helperUrl: getConfig().helperUrl,
    explorerUrl: getConfig().explorerUrl,
    account: slot.accountId,
    contract: slot.accessKeyContractId,
    publicKey: slot.publicKey,
  }
}

export const requestSignIn = async ({
  contractId,
  excludedWallets,
  features,
  network,
  signMessageParams,
}: {
  contractId?: string;
  excludedWallets?: string[];
  features?: Record<string, boolean>;
  network?: FastNearNetworkId;
  signMessageParams?: { message: string; recipient: string; nonce: Uint8Array };
} = {}) => {
  const provider = getWalletProvider();
  if (!provider) {
    throw new Error("No wallet provider set. Call useWallet() first or load the @fastnear/wallet IIFE bundle.");
  }

  const targetNetwork = network ?? getActiveNetwork();

  // Drop any prior session on the *target* network only — leaving sessions
  // on other networks intact. With @fastnear/wallet 1.1.0+ the optional
  // `{ network }` argument scopes both checks; older providers that ignore
  // the option fall back to "active network", which matches pre-1.1.2
  // behavior since `targetNetwork` defaulted to the active config.
  if (provider.isConnected({ network: targetNetwork })) {
    await provider.disconnect({ network: targetNetwork });
  }

  const result = await provider.connect({
    contractId,
    network: targetNetwork,
    excludedWallets,
    features,
    signMessageParams,
  });

  if (!result) {
    // User rejected
    return undefined;
  }

  // Write the connected account into the *target network*'s slot rather than
  // the legacy global, and make that network the active one — signing in to a
  // network is what "I am on this network now" means.
  //
  // Signing in deliberately does NOT rewrite `config.networkId`: that is the
  // caller's configured default, not a record of where the session went. Every
  // no-arg call resolves through the active network instead, so the two never
  // need to agree. `setActiveNetwork` persists, so this survives a reload.
  //
  // Keep the provider's public key when it gives us one — it was being dropped,
  // so `near.publicKey()` and `getPublicKeyForContract()` returned null for
  // every wallet session even though the value was right here. Written
  // conditionally so a provider that omits it can't clobber a key already
  // derived from a stored private key.
  updateAccountState(
    {
      accountId: result.accountId,
      ...(result.publicKey ? { publicKey: result.publicKey } : {}),
    },
    targetNetwork,
  );
  setActiveNetwork(targetNetwork);
  return result;
};

// Shared JSON-RPC `query`/`call_function` params builder for `view`/`view.many`.
function buildViewParams(spec: {
  contractId: string;
  methodName: string;
  args?: any;
  argsBase64?: string;
  blockId?: string;
}): Record<string, any> {
  const encodedArgs = spec.argsBase64 || (spec.args ? toBase64(JSON.stringify(spec.args)) : "");
  return withBlockId(
    {
      request_type: "call_function",
      account_id: spec.contractId,
      method_name: spec.methodName,
      args_base64: encodedArgs,
    },
    spec.blockId,
  );
}

const viewImpl = async ({
                          contractId,
                          methodName,
                          args,
                          argsBase64,
                          blockId,
                          useArchival,
                          network,
                        }: {
  contractId: string;
  methodName: string;
  args?: any;
  argsBase64?: string;
  blockId?: string;
  useArchival?: boolean;
  network?: FastNearNetworkId;
}) => {
  const queryResult = await sendRpc(
    "query",
    buildViewParams({ contractId, methodName, args, argsBase64, blockId }),
    { useArchival, network },
  );

  return parseJsonFromBytes(queryResult.result.result);
};

export interface ViewManySpec {
  contractId: string;
  methodName: string;
  args?: any;
  argsBase64?: string;
  blockId?: string;
  useArchival?: boolean;
  network?: FastNearNetworkId;
}

// `view.many`: run many contract view calls as a concurrency-limited fan-out
// (at most `batch.maxConcurrency` in flight), decoding each ok result exactly
// like `view`. NEAR RPC has no array batching, so calls aren't merged into one
// request.
async function viewMany(specs: ViewManySpec[]): Promise<BatchItemResult[]> {
  const { maxConcurrency } = resolveBatchConfig(getConfig());
  // Build + call + decode all happen inside `viewImpl`, wrapped per item, so a
  // malformed spec or a bad/decode-failing response settles as an error rather
  // than rejecting the whole set.
  return mapWithConcurrency(specs, maxConcurrency, async (spec): Promise<BatchItemResult> => {
    try {
      const result = await viewImpl(spec);
      return { status: "ok", result };
    } catch (error) {
      return { status: "error", kind: errorKind(error), error };
    }
  });
}

// `view(...)` stays callable exactly as before; `.many([...])` is the bulk form.
export const view = Object.assign(viewImpl, { many: viewMany });

