/**
 * The implicit account id (64-char lowercase hex) for an ed25519 public key —
 * the account that key controls with no on-chain AddKey. Only ed25519 keys map
 * to implicit accounts.
 */
export const implicitAccountId = (publicKey: string): string => {
  const { keyType, data } = decodeNearPublicKey(publicKey);
  if (keyType !== "ed25519") {
    throw new Error("Only ed25519 public keys map to implicit accounts");
  }
  return toHex(data);
};

/**
 * Create and fund a NEAR **testnet** account through the testnet helper faucet.
 * Testnet only — there is no mainnet faucet. POSTs `{ newAccountId, newKey }`
 * to the helper create endpoint and returns its JSON result.
 */
export const createFundedTestnetAccount = async ({
  newAccountId,
  publicKey,
}: {
  newAccountId: string;
  publicKey: string;
}) => {
  const response = await fetch("https://helper.testnet.near.org/account", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    // The helper expects `newAccountPublicKey`. Sending near-api-js's older
    // `newKey` spelling makes it dereference an undefined field and answer 400
    // with an internal TypeError, which reads like a caller-side mistake.
    body: JSON.stringify({ newAccountId, newAccountPublicKey: publicKey }),
  });
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      `Testnet faucet rejected the request (${response.status})` +
        `${detail ? `: ${detail}` : ""}` +
        " — the faucet is rate limited per IP and only creates <name>.testnet accounts.",
    );
  }
  return response.json();
};

function shouldPrintInteractiveSeparator(): boolean {
  if (typeof process === "undefined") {
    return false;
  }

  return Boolean(process.stdout?.isTTY);
}

export function print(value: unknown): void {
  if (shouldPrintInteractiveSeparator()) {
    console.log("");
  }

  if (
    value === null ||
    value === undefined ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean" ||
    typeof value === "bigint"
  ) {
    console.log(value);
    return;
  }

  try {
    console.log(JSON.stringify(value, null, 2));
  } catch {
    console.log(value);
  }
}

function requiredParam<T>(value: T | undefined | null, name: string): T {
  if (value === undefined || value === null || value === "") {
    throw new Error(`fastnear: missing required parameter "${name}"`);
  }
  return value;
}

function encodePathParam(value: string | number, name: string): string {
  return encodeURIComponent(String(requiredParam(value, name)));
}

function withAliases(
  params: Record<string, any>,
  aliases: Record<string, string>
): Record<string, any> {
  const next = { ...params };
  for (const [from, to] of Object.entries(aliases)) {
    if (next[from] !== undefined && next[to] === undefined) {
      next[to] = next[from];
    }
    delete next[from];
  }
  return next;
}

